def trans(grid):
    h=len(grid); w=len(grid[0])
    out=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            c=collections.Counter()
            for a,b in {(i,j),(i,w-1-j),(h-1-i,j),(h-1-i,w-1-j)}:
                c[grid[a][b]]+=2  # each orbit value appears twice per 4-pt set
            # 8-fold: also transpose-based flips not valid for non-square-sym; grid square
            out[i][j]=c.most_common(1)[0][0]
    return out
