def asym(grid):
    h,w=len(grid),len(grid[0]); c=collections.Counter()
    for i in range(h):
        for j in range(w):
            orb=[grid[a][b] for a,b in {(i,j),(i,w-1-j),(h-1-i,j),(h-1-i,w-1-j)}]
            for v in set(orb):
                if orb.count(v)!=4: c[v]+=1
    return c
def trans2(grid):
    h,w=len(grid),len(grid[0]); A=asym(grid)
    out=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            orb=[grid[a][b] for a,b in {(i,j),(i,w-1-j),(h-1-i,j),(h-1-i,w-1-j)}]
            c=collections.Counter(orb)
            top=c.most_common()
            if len(top)>1 and top[0][1]==top[1][1]:
                # tie: prefer value with lower asym score
                v=sorted({x for x,_ in top}, key=lambda v:(A[v],v))[0]
            else: v=top[0][0]
            out[i][j]=v
    return out
